// Daily Task Digest - Morning Briefing
// Tổng hợp tasks, events, và priorities trong ngày

const now = new Date();
const today = now.toISOString().split('T')[0];
const vietnamTime = now.toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' });

// Mock data - Thay thế bằng data từ các nodes thực tế
const tasks = {
  urgent: [],
  today: [],
  overdue: [],
  upcoming: []
};

const calendarEvents = [];
const focusItems = [];

return [{
  json: {
    date: today,
    vietnam_time: vietnamTime,
    tasks,
    calendar: calendarEvents,
    focus: focusItems,
    summary: {
      total_tasks: 0,
      urgent_count: 0,
      overdue_count: 0,
      meetings_today: 0
    }
  }
}];

// Generate Morning Briefing email/message
const briefing = $input.first().json;

const taskList = briefing.tasks.urgent.length > 0
  ? briefing.tasks.urgent.map((t, i) => `${i + 1}. ⚠️ ${t.title || t}`).join('\n')
  : briefing.tasks.today.map((t, i) => `${i + 1}. ${t.title || t}`).join('\n') || '✅ Không có tasks nào hôm nay!';

const meetingList = briefing.calendar.length > 0
  ? briefing.calendar.map(e => `• ${e.time || 'TBD'}: ${e.title || e}`).join('\n')
  : '📅 Không có meetings hôm nay!';

const message = {
  to: '', // Điền email của bạn
  subject: `📋 Morning Briefing - ${briefing.date}`,
  body: `Chào buổi sáng! ☀️

Đây là tóm tắt công việc hôm nay:

━━━━━━━━━━━━━━━━━━━━
📊 TỔNG QUAN
━━━━━━━━━━━━━━━━━━━━

Tasks khẩn cấp: ${briefing.summary.urgent_count}
Tasks hôm nay: ${briefing.summary.total_tasks}
Tasks quá hạn: ${briefing.summary.overdue_count}
Meetings: ${briefing.summary.meetings_today}

━━━━━━━━━━━━━━━━━━━━
✅ TASKS CẦN LÀM
━━━━━━━━━━━━━━━━━━━━

${taskList}

━━━━━━━━━━━━━━━━━━━━
📅 MEETINGS HÔM NAY
━━━━━━━━━━━━━━━━━━━━

${meetingList}

━━━━━━━━━━━━━━━━━━━━
🎯 FOCUS ITEMS
━━━━━━━━━━━━━━━━━━━━

${briefing.focus.length > 0 ? briefing.focus.map(f => `• ${f}`).join('\n') : 'Không có focus items'}

━━━━━━━━━━━━━━━━━━━━

💡 Lời khuyên: Hãy bắt đầu với task khẩn cấp nhất trước!

Chúc một ngày làm việc hiệu quả! 🚀`,
  briefing_data: briefing
};

return [{ json: message }];
